-- Records of agent_configs
-- ----------------------------
BEGIN;
INSERT INTO `agent_configs` (`id`, `agent_type`, `name`, `description`, `model`, `system_prompt`, `temperature`, `max_tokens`, `max_iterations`, `is_active`, `created_at`, `updated_at`, `deleted_at`, `created_by`, `updated_by`, `deleted_by`, `is_deleted`) VALUES (1, 'script_rewriter', '剧本改写', '', 'gemini-3.1-pro-preview', '', 0.7, 4096, 10, 1, '2026-05-18 15:19:47', '2026-05-18 15:29:12', NULL, 'migration', 'migration', NULL, 0);
INSERT INTO `agent_configs` (`id`, `agent_type`, `name`, `description`, `model`, `system_prompt`, `temperature`, `max_tokens`, `max_iterations`, `is_active`, `created_at`, `updated_at`, `deleted_at`, `created_by`, `updated_by`, `deleted_by`, `is_deleted`) VALUES (2, 'extractor', '角色场景提取', '', 'gemini-3.1-pro-preview', '', 0.7, 4096, 10, 1, '2026-05-18 15:19:47', '2026-05-18 15:29:12', NULL, 'migration', 'migration', NULL, 0);
INSERT INTO `agent_configs` (`id`, `agent_type`, `name`, `description`, `model`, `system_prompt`, `temperature`, `max_tokens`, `max_iterations`, `is_active`, `created_at`, `updated_at`, `deleted_at`, `created_by`, `updated_by`, `deleted_by`, `is_deleted`) VALUES (3, 'storyboard_breaker', '分镜拆解', '', 'gemini-3.1-pro-preview', '你是短剧影视分镜导演。必须把剧本拆成可直接用于图片、视频、配音、音效和合成流程的结构化分镜，而不是只生成 video_prompt。\n\n工作流程：\n1. 必须先调用 read_storyboard_context，读取 script、characters、scenes、storyboard_quality_guide。\n2. 按剧情节奏拆解为短视频镜头序列；通常 12-24 个镜头，简单片段可少一些，复杂剧情不要合并重大动作。\n3. 每个镜头通常 2-5 秒，转场或宏大空镜可到 8 秒。\n4. 必须调用 save_storyboards 保存完整 storyboards 数组。\n\n每条分镜必须完整填写：\n- shotNumber/shot_number：从 1 开始连续递增。\n- title：3-10 字镜头标题。\n- shotType/shot_type：必须使用标准枚举，优先 FULL_SHOT, CLOSE_UP, LONG_SHOT, MEDIUM_SHOT, EXTREME_CLOSE_UP, EXTREME_LONG_SHOT, MEDIUM_CLOSE_UP, OVER_SHOULDER, POV, TWO_SHOT, GROUP_SHOT。\n- cameraAngle/angle：必须使用标准枚举，优先 EYE_LEVEL, HIGH_ANGLE, LOW_ANGLE, BIRD_EYE, DUTCH_ANGLE, OVER_SHOULDER, POV。\n- cameraMovement/movement：必须使用标准枚举，优先 STATIC, ZOOM, PAN, TILT, DOLLY, TRACKING, PUSH_IN, PULL_OUT, HANDHELD, CRANE。\n- durationSeconds/duration：数字秒数，通常 2-5。\n- visualDescription/description：只写画面视觉，包括构图、景别、光线、材质、空间、环境细节和镜头看到的内容。\n- action：只写角色动作、表情、表演节奏和镜头内变化。\n- dialogue：该镜头实际对白或旁白；没有对白用 null 或空字符串。\n- soundEffects/sound_effect：关键音效，不能空。\n- backgroundMusic/bgm_prompt：配乐或氛围音乐，不能空。\n- atmosphere：镜头情绪、压迫感、紧张感、孤独感等，不能空。\n- sceneId/scene_id：必须来自 read_storyboard_context.scenes。非抽象镜头必须绑定场景。\n- charactersInShot/character_ids：必须只使用 read_storyboard_context.characters 中的角色 id；空镜头传空数组。\n- image_prompt：静态画面提示词，要能直接用于关键帧/首帧/尾帧生成。\n- video_prompt：动态视频提示词，要包含主体、动作、运镜、光线、场景连续性。', 0.7, 4096, 10, 1, '2026-05-18 15:19:47', '2026-05-18 15:29:12', NULL, 'migration', 'migration', NULL, 0);
INSERT INTO `agent_configs` (`id`, `agent_type`, `name`, `description`, `model`, `system_prompt`, `temperature`, `max_tokens`, `max_iterations`, `is_active`, `created_at`, `updated_at`, `deleted_at`, `created_by`, `updated_by`, `deleted_by`, `is_deleted`) VALUES (4, 'voice_assigner', '音色分配', '', 'gemini-3.1-pro-preview', '', 0.7, 4096, 10, 1, '2026-05-18 15:19:47', '2026-05-18 15:29:12', NULL, 'migration', 'migration', NULL, 0);
INSERT INTO `agent_configs` (`id`, `agent_type`, `name`, `description`, `model`, `system_prompt`, `temperature`, `max_tokens`, `max_iterations`, `is_active`, `created_at`, `updated_at`, `deleted_at`, `created_by`, `updated_by`, `deleted_by`, `is_deleted`) VALUES (5, 'grid_prompt_generator', '图片提示词生成', '', 'gemini-3.1-pro-preview', '', 0.7, 4096, 10, 1, '2026-05-18 15:19:47', '2026-05-18 15:29:12', NULL, 'migration', 'migration', NULL, 0);
COMMIT;

