DROP TABLE IF EXISTS `ai_model_billing_rules`;
CREATE TABLE `ai_model_billing_rules` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `model_config_id` bigint(20) NOT NULL COMMENT '模型配置ID',
  `service_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '服务类型',
  `parameter_type` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '参数类型',
  `parameter_value` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '参数值',
  `credits` int(11) NOT NULL DEFAULT '0' COMMENT '积分',
  `unit` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'request' COMMENT '单位',
  `created_by` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'migration' COMMENT '创建人',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_by` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'migration' COMMENT '修改人',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `deleted_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '删除人',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_model_billing_rule` (`model_config_id`,`parameter_type`,`parameter_value`)
) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AI模型计费规则表';

