-- ----------------------------
-- Table structure for ai_model_configs
-- ----------------------------
DROP TABLE IF EXISTS `ai_model_configs`;
CREATE TABLE `ai_model_configs` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `service_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '服务类型',
  `provider` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '供应商标识',
  `model_id` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模型ID',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '名称',
  `description` longtext COLLATE utf8mb4_unicode_ci COMMENT '描述',
  `base_url` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '接口基础地址',
  `endpoint` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '提交接口地址',
  `query_endpoint` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '查询接口地址',
  `parameters` longtext COLLATE utf8mb4_unicode_ci COMMENT '参数配置',
  `defaults` longtext COLLATE utf8mb4_unicode_ci COMMENT '默认参数',
  `capabilities` longtext COLLATE utf8mb4_unicode_ci COMMENT '能力配置',
  `cost` double DEFAULT '0' COMMENT '成本',
  `priority` int(11) DEFAULT '0' COMMENT '优先级',
  `is_default` int(11) DEFAULT '0' COMMENT '是否默认',
  `is_active` int(11) DEFAULT '1' COMMENT '是否启用',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `user_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '用户ID',
  `provider_id` bigint(20) DEFAULT NULL COMMENT '供应商ID',
  `source_model_id` bigint(20) DEFAULT NULL COMMENT '来源模型ID',
  `parameter_profile_id` bigint(20) DEFAULT NULL COMMENT '参数模板ID',
  `is_free` int(11) DEFAULT '0' COMMENT '是否免费',
  `image_credit_by_resolution` longtext COLLATE utf8mb4_unicode_ci COMMENT '图片分辨率积分配置',
  `video_credit_per_second_by_resolution` longtext COLLATE utf8mb4_unicode_ci COMMENT '视频分辨率每秒积分配置',
  `billing_config` longtext COLLATE utf8mb4_unicode_ci COMMENT '计费配置',
  `member_only` int(11) DEFAULT '0' COMMENT '是否会员专用',
  `created_by` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'migration' COMMENT '创建人',
  `updated_by` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'migration' COMMENT '修改人',
  `deleted_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '删除人',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除',
  PRIMARY KEY (`id`),
  KEY `idx_ai_model_configs_service_active_priority` (`service_type`,`is_active`,`priority`),
  KEY `idx_ai_model_configs_user_service_active_priority` (`user_id`,`service_type`,`is_active`,`priority`)
) ENGINE=InnoDB AUTO_INCREMENT=30 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AI模型配置表';

-- ----------------------------
-- Records of ai_model_configs
-- ----------------------------
