-- ----------------------------
-- Table structure for ai_model_parameter_profile_items
-- ----------------------------
DROP TABLE IF EXISTS `ai_model_parameter_profile_items`;
CREATE TABLE `ai_model_parameter_profile_items` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `profile_id` bigint(20) NOT NULL COMMENT 'profile_id',
  `type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '类型',
  `label` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标签',
  `value` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '值',
  `config` longtext COLLATE utf8mb4_unicode_ci COMMENT '配置',
  `rank` int(11) DEFAULT '0' COMMENT '排序权重',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `min_value` double DEFAULT NULL COMMENT '最小值',
  `max_value` double DEFAULT NULL COMMENT '最大值',
  `step_value` double DEFAULT NULL COMMENT '步长',
  `unit` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '单位',
  `placeholder` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '占位提示',
  `options_source` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '选项来源',
  `created_by` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'migration' COMMENT '创建人',
  `updated_by` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'migration' COMMENT '修改人',
  `deleted_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '删除人',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除',
  PRIMARY KEY (`id`),
  KEY `idx_ai_model_parameter_profile_items_profile_rank` (`profile_id`,`rank`,`updated_at`)
) ENGINE=InnoDB AUTO_INCREMENT=1019 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AI模型参数项表';

