-- ----------------------------
-- Table structure for ai_users
-- ----------------------------
DROP TABLE IF EXISTS `ai_users`;
CREATE TABLE `ai_users` (
  `id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键ID',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '名称',
  `email` varchar(160) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '邮箱',
  `role` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT 'user' COMMENT '角色',
  `is_active` int(11) DEFAULT '1' COMMENT '是否启用',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `account` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '账号',
  `password_hash` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '密码哈希',
  `invite_code` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '邀请码',
  `phone` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '手机号',
  `credits` int(11) DEFAULT '0' COMMENT '积分',
  `membership_plan_id` bigint(20) DEFAULT NULL COMMENT '会员套餐ID',
  `membership_status` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT 'none' COMMENT '会员状态',
  `membership_expires_at` datetime DEFAULT NULL COMMENT '会员到期时间',
  `balance` double NOT NULL DEFAULT '0' COMMENT '余额',
  `created_by` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'migration' COMMENT '创建人',
  `updated_by` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'migration' COMMENT '修改人',
  `deleted_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '删除人',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除',
  `membership_credits` int(11) NOT NULL DEFAULT '0' COMMENT '会员积分余额',
  `membership_period_credits` int(11) NOT NULL DEFAULT '0' COMMENT '会员每期发放积分',
  `membership_started_at` datetime DEFAULT NULL COMMENT '会员开始时间',
  `membership_next_grant_at` datetime DEFAULT NULL COMMENT '会员下次积分发放时间',
  `membership_last_grant_at` datetime DEFAULT NULL COMMENT '会员上次积分发放时间',
  `wx_openid` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '微信OpenID',
  `wx_unionid` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '微信UnionID',
  `wx_nickname` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '微信昵称',
  `wx_avatar` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '微信头像',
  `wx_bound_at` datetime DEFAULT NULL COMMENT '微信绑定时间',
  `last_login_at` datetime DEFAULT NULL COMMENT '最后登录时间',
  `last_login_ip` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '最后登录IP',
  `login_channel` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'password' COMMENT '登录渠道',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ai_users_account` (`account`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='用户表';

