DROP TABLE IF EXISTS `assets`;
CREATE TABLE `assets` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `drama_id` bigint(20) DEFAULT NULL COMMENT '短剧ID',
  `episode_id` bigint(20) DEFAULT NULL COMMENT '剧集ID',
  `storyboard_id` bigint(20) DEFAULT NULL COMMENT '分镜ID',
  `storyboard_num` int(11) DEFAULT NULL COMMENT 'storyboard_num',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '名称',
  `description` longtext COLLATE utf8mb4_unicode_ci COMMENT '描述',
  `type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '类型',
  `category` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '分类',
  `url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '地址',
  `thumbnail_url` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '缩略图地址',
  `local_path` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '本地路径',
  `file_size` int(11) DEFAULT NULL COMMENT '文件大小',
  `mime_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'MIME类型',
  `width` int(11) DEFAULT NULL COMMENT '宽度',
  `height` int(11) DEFAULT NULL COMMENT '高度',
  `duration` int(11) DEFAULT NULL COMMENT '时长',
  `format` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '格式',
  `image_gen_id` bigint(20) DEFAULT NULL COMMENT '图片生成ID',
  `video_gen_id` bigint(20) DEFAULT NULL COMMENT '视频生成ID',
  `is_favorite` int(11) DEFAULT '0' COMMENT '是否收藏',
  `view_count` int(11) DEFAULT '0' COMMENT '查看次数',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  `created_by` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'migration' COMMENT '创建人',
  `updated_by` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'migration' COMMENT '修改人',
  `deleted_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '删除人',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='素材资源表';

