-- ----------------------------
-- Table structure for character_library
-- ----------------------------
DROP TABLE IF EXISTS `character_library`;
CREATE TABLE `character_library` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '名称',
  `age` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '年龄',
  `gender` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '性别',
  `role` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '角色',
  `description` longtext COLLATE utf8mb4_unicode_ci COMMENT '描述',
  `appearance` longtext COLLATE utf8mb4_unicode_ci COMMENT '外观描述',
  `personality` longtext COLLATE utf8mb4_unicode_ci COMMENT '性格描述',
  `voice_style` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '声音风格',
  `image_url` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '图片地址',
  `reference_images` longtext COLLATE utf8mb4_unicode_ci COMMENT '参考图片',
  `source_character_id` bigint(20) DEFAULT NULL COMMENT '来源角色ID',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  `created_by` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'migration' COMMENT '创建人',
  `updated_by` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'migration' COMMENT '修改人',
  `deleted_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '删除人',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='角色库表';

-- ----------------------------
-- Records of character_library
-- ----------------------------
BEGIN;
INSERT INTO `character_library` (`id`, `name`, `age`, `gender`, `role`, `description`, `appearance`, `personality`, `voice_style`, `image_url`, `reference_images`, `source_character_id`, `created_at`, `updated_at`, `deleted_at`, `created_by`, `updated_by`, `deleted_by`, `is_deleted`) VALUES (1, '皇帝', '中年', '男', '配角', '盛唐最高统治者，掌握生杀予夺之权。对突然闯入朝局、来历不明的“男官”保持高度警惕，以“当殿作诗”设下生死之试，考量其胆识与真才。闻得诗句震世，他由怀疑转为认可，展现出在威严外表下重视学问与气魄的帝王风骨；既能以威压震慑群臣，也能在关键时刻褒奖真才，为后续朝堂走向埋下转机。与朝臣保持制衡，与沈昭昭形成君臣之间的知遇关系雏形。', '中年男性，体态端凝，肩背宽阔而不臃肿，坐姿沉稳。发束高冠，额前整齐，鬓发微霜，颏下修短须，衬出威仪。身着龙纹朝服，锦地厚实，纹理层次分明，色泽沉稳不炫；袖口宽大，举手投足带出衣摆缓缓的褶影。腰间束以纹带，饰件简而贵，步伐极稳。面部线条硬朗，鼻梁挺直，眼神深而锐，目光落处自带威压；平视时神情内敛，隐有审度与猜疑。龙椅高踞殿端，他多端坐，偶有缓立，衣袍在背光里泛起低沉金光。高窗斜光勾出眉骨与颧弓的明暗棱线，轮廓更显冷峻。整体气场冷静克制、威严厚重，在听到惊艳诗句时眉眼微动，威严中透出欣赏与爱才的暖意。', '威严、沉稳、多疑而爱才、果断、审慎', '', 'static/images/095098b1-773c-41e6-a2a8-410cc25749b9.png', NULL, 2, '2026-05-18 10:09:13', '2026-05-18 10:09:13', NULL, 'migration', 'migration', NULL, 0);
INSERT INTO `character_library` (`id`, `name`, `age`, `gender`, `role`, `description`, `appearance`, `personality`, `voice_style`, `image_url`, `reference_images`, `source_character_id`, `created_at`, `updated_at`, `deleted_at`, `created_by`, `updated_by`, `deleted_by`, `is_deleted`) VALUES (2, '大臣', '中年', '男', '龙套', '朝中保守派代表人物之一，率先在金銮殿发难，指控沈昭昭“欺君罔上”，推动冲突升级，是威压与舆论的具体发起者。言语锋利，讲求礼制与成规，以道统名分为武器，期望以严刑整肃朝纲。在皇帝与群臣之间，他多以表态与煽动试探帝意；与沈昭昭形成直接对立，为其以文才破局提供反衬。', '年长男性，身形略瘦而挺直，步履拘谨。头戴幞头或朝冠，额际平整，鬓发花白。面皮薄而紧，法令深，唇线收束，常呈不苟的冷硬神情。着唐代官服，圆领宽袖，衣摆垂直，色泽端肃；腰间束带，佩饰从简，行礼时衣袖并拢，动作严整。发言多以袖手或执笏板，声音尖厉而掷地，吐字清晰。站于班列前缘时脚尖微内扣、肩背紧绷，显示谨慎与强硬并存。近观目光凌厉，常以上挑或侧斜目光审度对手；俯身进谏时颈项与下颌线拉直，显出倨傲与自守。整体气息冷峻、衣褶笔挺，给人守礼而不近人情之感，形塑朝堂保守力量的象征。', '严苛、守旧、谨慎、攻击性强、循规蹈矩', '', 'static/images/ab1a00f5-3c88-472d-9938-0289ccb13b54.png', NULL, 3, '2026-05-18 10:12:22', '2026-05-18 10:12:22', NULL, 'migration', 'migration', NULL, 0);
INSERT INTO `character_library` (`id`, `name`, `age`, `gender`, `role`, `description`, `appearance`, `personality`, `voice_style`, `image_url`, `reference_images`, `source_character_id`, `created_at`, `updated_at`, `deleted_at`, `created_by`, `updated_by`, `deleted_by`, `is_deleted`) VALUES (3, '沈昭昭', '成年', '女', '主角', '现代都市白领，因高强度加班在深夜办公室突然黑屏眩晕，转瞬跪于盛唐金銮殿，身份被误作冒名夸耀才名的“男官”。生死一线间，她以熟识的古典诗词脱险，当殿吟出“君不见黄河之水天上来”，震动百官，扭转皇帝的观感。她由慌乱到沉着，展露过目不忘与临场整合能力，奠定以文才自证、与盛唐命运相搏的开局；与皇帝由试探到被认可，与保守派大臣形成天然对立。', '女性，约28岁，身量中等，清瘦而匀称。现代场景中，长时间伏案导致面色偏白，鼻梁与颧处透出细微倦意，眼下有浅浅暗影，唇色淡，指节因高频敲击而略显干瘦。五官清秀，眉形利落，神情专注而紧绷。穿越至殿上时已换为唐代男装官服：内着贴体直裾，外披宽袖官袍，腰间细束，线条干净，衣襟收合以掩女性曲线；衣料沉稳，无过多纹饰，利于行动。黑发束起，绾成简练发髻，以男子礼制固定，鬓角服帖。初到大殿双手被缚，膝行跪地仍保持脊背挺直，重心稳固；刀光映瞳，呼吸由急转缓。吟诗时抬颌直视，嗓音清亮，声线由怯生到铿锵，目光在日光与殿内冷光交织中愈发清澈，呈现克制而坚韧的气质，举止干净利落，散发出超越处境的镇定。', '处变不惊、聪慧果敢、敏锐、坚韧、适应力强', '', 'static/images/6f70adaf-cf0e-4c5d-8a6d-5d2bfeac4cdc.png', NULL, 1, '2026-05-18 14:24:24', '2026-05-18 14:24:24', NULL, 'migration', 'migration', NULL, 0);
COMMIT;

-- ----------------------------
-- Table structure for characters
-- ----------------------------
DROP TABLE IF EXISTS `characters`;
CREATE TABLE `characters` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `drama_id` bigint(20) NOT NULL COMMENT '短剧ID',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '名称',
  `role` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '角色',
  `description` longtext COLLATE utf8mb4_unicode_ci COMMENT '描述',
  `appearance` longtext COLLATE utf8mb4_unicode_ci COMMENT '外观描述',
  `personality` longtext COLLATE utf8mb4_unicode_ci COMMENT '性格描述',
  `voice_style` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '声音风格',
  `image_url` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '图片地址',
  `reference_images` longtext COLLATE utf8mb4_unicode_ci COMMENT '参考图片',
  `seed_value` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '种子值',
  `sort_order` int(11) DEFAULT NULL COMMENT '排序值',
  `local_path` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '本地路径',
  `voice_sample_url` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '声音样本地址',
  `voice_provider` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '声音供应商',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  `age` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '年龄',
  `gender` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '性别',
  `created_by` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'migration' COMMENT '创建人',
  `updated_by` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'migration' COMMENT '修改人',
  `deleted_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '删除人',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='角色表';

-- ----------------------------
-- Records of characters
-- ----------------------------
BEGIN;
INSERT INTO `characters` (`id`, `drama_id`, `name`, `role`, `description`, `appearance`, `personality`, `voice_style`, `image_url`, `reference_images`, `seed_value`, `sort_order`, `local_path`, `voice_sample_url`, `voice_provider`, `created_at`, `updated_at`, `deleted_at`, `age`, `gender`, `created_by`, `updated_by`, `deleted_by`, `is_deleted`) VALUES (1, 1, '沈昭昭', '主角', '现代都市白领，因高强度加班在深夜办公室突然黑屏眩晕，转瞬跪于盛唐金銮殿，身份被误作冒名夸耀才名的“男官”。生死一线间，她以熟识的古典诗词脱险，当殿吟出“君不见黄河之水天上来”，震动百官，扭转皇帝的观感。她由慌乱到沉着，展露过目不忘与临场整合能力，奠定以文才自证、与盛唐命运相搏的开局；与皇帝由试探到被认可，与保守派大臣形成天然对立。', '女性，约28岁，身量中等，清瘦而匀称。现代场景中，长时间伏案导致面色偏白，鼻梁与颧处透出细微倦意，眼下有浅浅暗影，唇色淡，指节因高频敲击而略显干瘦。五官清秀，眉形利落，神情专注而紧绷。穿越至殿上时已换为唐代男装官服：内着贴体直裾，外披宽袖官袍，腰间细束，线条干净，衣襟收合以掩女性曲线；衣料沉稳，无过多纹饰，利于行动。黑发束起，绾成简练发髻，以男子礼制固定，鬓角服帖。初到大殿双手被缚，膝行跪地仍保持脊背挺直，重心稳固；刀光映瞳，呼吸由急转缓。吟诗时抬颌直视，嗓音清亮，声线由怯生到铿锵，目光在日光与殿内冷光交织中愈发清澈，呈现克制而坚韧的气质，举止干净利落，散发出超越处境的镇定。', '处变不惊、聪慧果敢、敏锐、坚韧、适应力强', NULL, 'static/images/6f70adaf-cf0e-4c5d-8a6d-5d2bfeac4cdc.png', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-18 04:12:27', '2026-05-18 09:45:04', NULL, '成年', '女', 'migration', 'migration', NULL, 0);
INSERT INTO `characters` (`id`, `drama_id`, `name`, `role`, `description`, `appearance`, `personality`, `voice_style`, `image_url`, `reference_images`, `seed_value`, `sort_order`, `local_path`, `voice_sample_url`, `voice_provider`, `created_at`, `updated_at`, `deleted_at`, `age`, `gender`, `created_by`, `updated_by`, `deleted_by`, `is_deleted`) VALUES (2, 1, '皇帝', '配角', '盛唐最高统治者，掌握生杀予夺之权。对突然闯入朝局、来历不明的“男官”保持高度警惕，以“当殿作诗”设下生死之试，考量其胆识与真才。闻得诗句震世，他由怀疑转为认可，展现出在威严外表下重视学问与气魄的帝王风骨；既能以威压震慑群臣，也能在关键时刻褒奖真才，为后续朝堂走向埋下转机。与朝臣保持制衡，与沈昭昭形成君臣之间的知遇关系雏形。', '中年男性，体态端凝，肩背宽阔而不臃肿，坐姿沉稳。发束高冠，额前整齐，鬓发微霜，颏下修短须，衬出威仪。身着龙纹朝服，锦地厚实，纹理层次分明，色泽沉稳不炫；袖口宽大，举手投足带出衣摆缓缓的褶影。腰间束以纹带，饰件简而贵，步伐极稳。面部线条硬朗，鼻梁挺直，眼神深而锐，目光落处自带威压；平视时神情内敛，隐有审度与猜疑。龙椅高踞殿端，他多端坐，偶有缓立，衣袍在背光里泛起低沉金光。高窗斜光勾出眉骨与颧弓的明暗棱线，轮廓更显冷峻。整体气场冷静克制、威严厚重，在听到惊艳诗句时眉眼微动，威严中透出欣赏与爱才的暖意。', '威严、沉稳、多疑而爱才、果断、审慎', NULL, 'static/images/095098b1-773c-41e6-a2a8-410cc25749b9.png', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-18 04:12:27', '2026-05-18 09:45:19', NULL, '中年', '男', 'migration', 'migration', NULL, 0);
INSERT INTO `characters` (`id`, `drama_id`, `name`, `role`, `description`, `appearance`, `personality`, `voice_style`, `image_url`, `reference_images`, `seed_value`, `sort_order`, `local_path`, `voice_sample_url`, `voice_provider`, `created_at`, `updated_at`, `deleted_at`, `age`, `gender`, `created_by`, `updated_by`, `deleted_by`, `is_deleted`) VALUES (3, 1, '大臣', '龙套', '朝中保守派代表人物之一，率先在金銮殿发难，指控沈昭昭“欺君罔上”，推动冲突升级，是威压与舆论的具体发起者。言语锋利，讲求礼制与成规，以道统名分为武器，期望以严刑整肃朝纲。在皇帝与群臣之间，他多以表态与煽动试探帝意；与沈昭昭形成直接对立，为其以文才破局提供反衬。', '年长男性，身形略瘦而挺直，步履拘谨。头戴幞头或朝冠，额际平整，鬓发花白。面皮薄而紧，法令深，唇线收束，常呈不苟的冷硬神情。着唐代官服，圆领宽袖，衣摆垂直，色泽端肃；腰间束带，佩饰从简，行礼时衣袖并拢，动作严整。发言多以袖手或执笏板，声音尖厉而掷地，吐字清晰。站于班列前缘时脚尖微内扣、肩背紧绷，显示谨慎与强硬并存。近观目光凌厉，常以上挑或侧斜目光审度对手；俯身进谏时颈项与下颌线拉直，显出倨傲与自守。整体气息冷峻、衣褶笔挺，给人守礼而不近人情之感，形塑朝堂保守力量的象征。', '严苛、守旧、谨慎、攻击性强、循规蹈矩', NULL, 'static/images/ab1a00f5-3c88-472d-9938-0289ccb13b54.png', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-18 04:12:27', '2026-05-18 09:44:53', NULL, '中年', '男', 'migration', 'migration', NULL, 0);
INSERT INTO `characters` (`id`, `drama_id`, `name`, `role`, `description`, `appearance`, `personality`, `voice_style`, `image_url`, `reference_images`, `seed_value`, `sort_order`, `local_path`, `voice_sample_url`, `voice_provider`, `created_at`, `updated_at`, `deleted_at`, `age`, `gender`, `created_by`, `updated_by`, `deleted_by`, `is_deleted`) VALUES (4, 1, '角色4', '角色', '请补充角色描述', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-18 09:44:41', '2026-05-18 09:44:41', '2026-05-18 01:44:46', '', '', 'migration', 'migration', 'migration', 1);
COMMIT;

-- ----------------------------
-- Table structure for creation_history
-- ----------------------------
DROP TABLE IF EXISTS `creation_history`;
CREATE TABLE `creation_history` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `task_id` bigint(20) NOT NULL COMMENT '任务ID',
  `user_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '用户ID',
  `type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'image' COMMENT '类型',
  `provider` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '供应商标识',
  `model` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '模型',
  `prompt` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '提示词',
  `result_url` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '结果地址',
  `local_path` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '本地路径',
  `mime_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'MIME类型',
  `width` int(11) DEFAULT NULL COMMENT '宽度',
  `height` int(11) DEFAULT NULL COMMENT '高度',
  `duration` int(11) DEFAULT NULL COMMENT '时长',
  `sort_order` int(11) DEFAULT '0' COMMENT '排序值',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'completed' COMMENT '状态',
  `error_msg` longtext COLLATE utf8mb4_unicode_ci COMMENT '错误信息',
  `metadata` longtext COLLATE utf8mb4_unicode_ci COMMENT '扩展数据',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  `created_by` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'migration' COMMENT '创建人',
  `updated_by` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'migration' COMMENT '修改人',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `deleted_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '删除人',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除',
  PRIMARY KEY (`id`),
  KEY `idx_creation_history_task` (`task_id`,`sort_order`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='创作历史表';

