-- ----------------------------
-- Table structure for dramas
-- ----------------------------
DROP TABLE IF EXISTS `dramas`;
CREATE TABLE `dramas` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标题',
  `description` longtext COLLATE utf8mb4_unicode_ci COMMENT '描述',
  `genre` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '题材',
  `style` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT 'realistic' COMMENT '风格',
  `total_episodes` int(11) DEFAULT '1' COMMENT '总集数',
  `total_duration` int(11) DEFAULT '0' COMMENT '总时长',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft' COMMENT '状态',
  `thumbnail` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '封面图',
  `tags` longtext COLLATE utf8mb4_unicode_ci COMMENT '标签',
  `metadata` longtext COLLATE utf8mb4_unicode_ci COMMENT '扩展数据',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  `created_by` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'migration' COMMENT '创建人',
  `updated_by` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'migration' COMMENT '修改人',
  `deleted_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '删除人',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='短剧项目表';

