DROP TABLE IF EXISTS `episodes`;
CREATE TABLE `episodes` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `drama_id` bigint(20) NOT NULL COMMENT '短剧ID',
