INSERT INTO `episodes` (`id`, `drama_id`, `episode_number`, `title`, `content`, `script_content`, `description`, `duration`, `status`, `video_url`, `thumbnail`, `image_config_id`, `video_config_id`, `audio_config_id`, `created_at`, `updated_at`, `deleted_at`, `created_by`, `updated_by`, `deleted_by`, `is_deleted`) VALUES (1, 1, 1, '第1集', '《我在盛唐写天下》\n\n**类型**：古风 / 穿越 / 爽文漫剧\n\n**时长建议**：60–90秒\n\n**基调**：热血 × 盛唐史诗感 × 爽点节奏\n\n【序幕】\n\n【现代 · 深夜办公室】\n\n键盘声急促。电脑屏幕蓝光刺眼。 沈昭昭（女，28岁），面色苍白，伏案加班。 手机提示音不断。 她抬头，视线模糊—— 黑屏。\n\n【第一幕】\n\n【盛唐 · 金銮殿 · 日】\n\n鼓声震天。 沈昭昭猛然睁眼，已跪在大殿中央，身着男装官服，双手被押。 百官列立，殿宇巍峨。 大臣厉声： “大逆不道！假称诗才惊世，欺君罔上，当斩！” 沈昭昭震惊低语： “这是……唐朝？” 龙椅之上，皇帝目光沉沉。 皇帝： “既言才华盖世，当殿作诗。若不能——斩。” 刀光映入她瞳孔。 大殿死寂。 【第二幕】 沈昭昭缓缓起身。 呼吸渐稳。 她望向殿外—— 长安城阳光万里。 她低声： “既来盛唐……便与盛唐争一争。” 抬头，高声吟诵： “君不见黄河之水天上来——” 声音回荡大殿。 群臣震动。 皇帝缓缓站起。 诗声激昂，如惊雷落殿。 【第三幕】 殿外风起。 长安街市灯火连绵。 皇帝低声： “此诗，当传万世。” 沈昭昭目光坚定。 她轻声自语： “既然来了……那便写尽三万里长安。” 镜头推远。 盛唐山河展开。', '《我在盛唐写天下》\n\n**类型**：古风 / 穿越 / 爽文漫剧\n\n**时长建议**：60–90秒\n\n**基调**：热血 × 盛唐史诗感 × 爽点节奏\n\n【序幕】\n\n【现代 · 深夜办公室】\n\n键盘声急促。电脑屏幕蓝光刺眼。 沈昭昭（女，28岁），面色苍白，伏案加班。 手机提示音不断。 她抬头，视线模糊—— 黑屏。\n\n【第一幕】\n\n【盛唐 · 金銮殿 · 日】\n\n鼓声震天。 沈昭昭猛然睁眼，已跪在大殿中央，身着男装官服，双手被押。 百官列立，殿宇巍峨。 大臣厉声： “大逆不道！假称诗才惊世，欺君罔上，当斩！” 沈昭昭震惊低语： “这是……唐朝？” 龙椅之上，皇帝目光沉沉。 皇帝： “既言才华盖世，当殿作诗。若不能——斩。” 刀光映入她瞳孔。 大殿死寂。 【第二幕】 沈昭昭缓缓起身。 呼吸渐稳。 她望向殿外—— 长安城阳光万里。 她低声： “既来盛唐……便与盛唐争一争。” 抬头，高声吟诵： “君不见黄河之水天上来——” 声音回荡大殿。 群臣震动。 皇帝缓缓站起。 诗声激昂，如惊雷落殿。 【第三幕】 殿外风起。 长安街市灯火连绵。 皇帝低声： “此诗，当传万世。” 沈昭昭目光坚定。 她轻声自语： “既然来了……那便写尽三万里长安。” 镜头推远。 盛唐山河展开。', NULL, 1, 'draft', NULL, NULL, NULL, NULL, NULL, '2026-05-18 01:36:33', '2026-05-18 13:56:50', NULL, 'migration', 'migration', NULL, 0);
