-- ----------------------------
-- Table structure for image_generations
-- ----------------------------
DROP TABLE IF EXISTS `image_generations`;
CREATE TABLE `image_generations` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `storyboard_id` bigint(20) DEFAULT NULL COMMENT '分镜ID',
  `drama_id` bigint(20) DEFAULT NULL COMMENT '短剧ID',
  `scene_id` bigint(20) DEFAULT NULL COMMENT '场景ID',
  `character_id` bigint(20) DEFAULT NULL COMMENT '角色ID',
  `prop_id` bigint(20) DEFAULT NULL COMMENT 'prop_id',
  `image_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '图片类型',
  `frame_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '帧类型',
  `provider` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '供应商标识',
  `prompt` longtext COLLATE utf8mb4_unicode_ci COMMENT '提示词',
  `negative_prompt` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '反向提示词',
  `model` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '模型',
  `size` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '尺寸',
  `quality` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '质量',
  `style` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '风格',
  `steps` int(11) DEFAULT NULL COMMENT '步数',
  `cfg_scale` double DEFAULT NULL COMMENT 'CFG参数',
  `seed` bigint(20) DEFAULT NULL COMMENT '随机种子',
  `image_url` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '图片地址',
  `minio_url` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '对象存储地址',
  `local_path` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '本地路径',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT 'pending' COMMENT '状态',
  `task_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '任务ID',
  `error_msg` longtext COLLATE utf8mb4_unicode_ci COMMENT '错误信息',
  `width` int(11) DEFAULT NULL COMMENT '宽度',
  `height` int(11) DEFAULT NULL COMMENT '高度',
  `reference_images` longtext COLLATE utf8mb4_unicode_ci COMMENT '参考图片',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `completed_at` datetime DEFAULT NULL COMMENT '完成时间',
  `sample_image_size` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '示例图片尺寸',
  `created_by` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'migration' COMMENT '创建人',
  `updated_by` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'migration' COMMENT '修改人',
  `deleted_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '删除人',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除',
  `mask` longtext COLLATE utf8mb4_unicode_ci COMMENT '局部编辑蒙版图',
  `output_format` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '图片输出格式',
  `response_format` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '图片响应格式',
  `watermark` tinyint(1) DEFAULT NULL COMMENT '是否添加水印',
  `stream` tinyint(1) DEFAULT NULL COMMENT '是否流式输出',
  `sequential_image_generation` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '组图生成模式',
  `sequential_image_generation_options` json DEFAULT NULL COMMENT '组图生成选项',
  `optimize_prompt_options` json DEFAULT NULL COMMENT '提示词优化选项',
  `tools` json DEFAULT NULL COMMENT '图片生成工具配置',
  `official_fallback` tinyint(1) DEFAULT NULL COMMENT 'APIMart 是否使用官方渠道兜底',
  `output_compression` int(11) DEFAULT NULL COMMENT '图片输出压缩强度 0-100',
  `background` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '图片背景模式',
  `moderation` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '图片审核强度',
  `google_search` tinyint(1) DEFAULT NULL COMMENT '是否启用 Google 文字搜索增强',
  `google_image_search` tinyint(1) DEFAULT NULL COMMENT '是否启用 Google 图片搜索增强',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='图片生成记录表';

-- ----------------------------
-- Records of image_generations
-- ----------------------------
