INSERT INTO `image_generations` (`id`, `storyboard_id`, `drama_id`, `scene_id`, `character_id`, `prop_id`, `image_type`, `frame_type`, `provider`, `prompt`, `negative_prompt`, `model`, `size`, `quality`, `style`, `steps`, `cfg_scale`, `seed`, `image_url`, `minio_url`, `local_path`, `status`, `task_id`, `error_msg`, `width`, `height`, `reference_images`, `created_at`, `updated_at`, `completed_at`, `sample_image_size`, `created_by`, `updated_by`, `deleted_by`, `deleted_at`, `is_deleted`, `mask`, `output_format`, `response_format`, `watermark`, `stream`, `sequential_image_generation`, `sequential_image_generation_options`, `optimize_prompt_options`, `tools`, `official_fallback`, `output_compression`, `background`, `moderation`, `google_search`, `google_image_search`) VALUES (1, NULL, 1, NULL, 1, NULL, NULL, NULL, 'zenmux', '角色名称：沈昭昭\n性别：女\n年龄阶段：成年\n角色身份：主角\n人物外貌与画面描述：女性，约28岁，身量中等，清瘦而匀称。现代场景中，长时间伏案导致面色偏白，鼻梁与颧处透出细微倦意，眼下有浅浅暗影，唇色淡，指节因高频敲击而略显干瘦。五官清秀，眉形利落，神情专注而紧绷。穿越至殿上时已换为唐代男装官服：内着贴体直裾，外披宽袖官袍，腰间细束，线条干净，衣襟收合以掩女性曲线；衣料沉稳，无过多纹饰，利于行动。黑发束起，绾成简练发髻，以男子礼制固定，鬓角服帖。初到大殿双手被缚，膝行跪地仍保持脊背挺直，重心稳固；刀光映瞳，呼吸由急转缓。吟诗时抬颌直视，嗓音清亮，声线由怯生到铿锵，目光在日光与殿内冷光交织中愈发清澈，呈现克制而坚韧的气质，举止干净利落，散发出超越处境的镇定。\n背景故事与人物设定：现代都市白领，因高强度加班在深夜办公室突然黑屏眩晕，转瞬跪于盛唐金銮殿，身份被误作冒名夸耀才名的“男官”。生死一线间，她以熟识的古典诗词脱险，当殿吟出“君不见黄河之水天上来”，震动百官，扭转皇帝的观感。她由慌乱到沉着，展露过目不忘与临场整合能力，奠定以文才自证、与盛唐命运相搏的开局；与皇帝由试探到被认可，与保守派大臣形成天然对立。\n性格气质：处变不惊、聪慧果敢、敏锐、坚韧、适应力强\n请根据以上角色卡片信息生成单人角色形象图。\n要求：角色主体清晰，正面或半身构图，人物特征稳定，服装、气质、时代背景与角色设定一致，高质量，细节丰富，干净背景，不要出现文字、水印、多人或无关元素。', NULL, 'gpt-image-2', '1920x1080', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'static/images/6f70adaf-cf0e-4c5d-8a6d-5d2bfeac4cdc.png', 'completed', NULL, NULL, NULL, NULL, NULL, '2026-05-18 09:41:48', '2026-05-18 09:45:04', NULL, NULL, 'migration', 'migration', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
