-- ----------------------------
-- Table structure for membership_plans
-- ----------------------------
DROP TABLE IF EXISTS `membership_plans`;
CREATE TABLE `membership_plans` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '名称',
  `code` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'code',
  `description` longtext COLLATE utf8mb4_unicode_ci COMMENT '描述',
  `price` double DEFAULT '0' COMMENT '价格',
  `credits` int(11) DEFAULT '0' COMMENT '积分',
  `duration_days` int(11) DEFAULT '30' COMMENT '有效天数',
  `sort_order` int(11) DEFAULT '0' COMMENT '排序值',
  `is_active` int(11) DEFAULT '1' COMMENT '是否启用',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `plan_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT 'creator' COMMENT '套餐类型',
  `billing_cycle` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT 'yearly' COMMENT '计费周期',
  `original_price` double DEFAULT '0' COMMENT '原价',
  `badge` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '角标',
  `subtitle` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '副标题',
  `metadata` longtext COLLATE utf8mb4_unicode_ci COMMENT '扩展数据',
  `created_by` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'migration' COMMENT '创建人',
  `updated_by` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'migration' COMMENT '修改人',
  `deleted_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '删除人',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_membership_plans_code` (`code`)
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='会员套餐表';

-- ----------------------------
-- Records of membership_plans
