-- ----------------------------
-- Table structure for orders
-- ----------------------------
DROP TABLE IF EXISTS `orders`;
CREATE TABLE `orders` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `order_no` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '订单号',
  `user_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用户ID',
  `type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '类型',
  `item_id` bigint(20) DEFAULT NULL COMMENT '商品ID',
  `item_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '商品名称',
  `amount` double DEFAULT '0' COMMENT '数量',
  `credits` int(11) DEFAULT '0' COMMENT '积分',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT 'pending' COMMENT '状态',
  `payment_provider` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '支付供应商',
  `payment_channel` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '支付渠道',
  `transaction_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '支付交易号',
  `metadata` longtext COLLATE utf8mb4_unicode_ci COMMENT '扩展数据',
  `paid_at` datetime DEFAULT NULL COMMENT '支付时间',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `expires_at` datetime DEFAULT NULL COMMENT '过期时间',
  `offline_voucher_url` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '线下支付凭证',
  `offline_remark` longtext COLLATE utf8mb4_unicode_ci COMMENT '线下备注',
  `created_by` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'migration' COMMENT '创建人',
  `updated_by` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'migration' COMMENT '修改人',
  `deleted_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '删除人',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_orders_order_no` (`order_no`),
  KEY `idx_orders_user_status_created` (`user_id`,`status`,`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='订单表';

-- ----------------------------
-- Records of orders
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for payment_configs
-- ----------------------------
DROP TABLE IF EXISTS `payment_configs`;
CREATE TABLE `payment_configs` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `provider` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '供应商标识',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '名称',
  `app_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '应用ID',
  `merchant_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '商户ID',
  `api_key` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '接口密钥',
  `api_secret` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '接口密钥Secret',
  `notify_url` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '回调地址',
  `return_url` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '返回地址',
  `config` longtext COLLATE utf8mb4_unicode_ci COMMENT '配置',
  `is_default` int(11) DEFAULT '0' COMMENT '是否默认',
  `is_active` int(11) DEFAULT '1' COMMENT '是否启用',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `created_by` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'migration' COMMENT '创建人',
  `updated_by` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'migration' COMMENT '修改人',
  `deleted_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '删除人',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除',
  PRIMARY KEY (`id`),
  KEY `idx_payment_configs_provider` (`provider`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='支付配置表';

-- ----------------------------
-- Records of payment_configs
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for points_logs
-- ----------------------------
DROP TABLE IF EXISTS `points_logs`;
CREATE TABLE `points_logs` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用户ID',
  `amount` int(11) NOT NULL COMMENT '数量',
  `balance` int(11) DEFAULT '0' COMMENT '余额',
  `type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '类型',
  `description` longtext COLLATE utf8mb4_unicode_ci COMMENT '描述',
  `related_order_id` bigint(20) DEFAULT NULL COMMENT '关联订单ID',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `related_task_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联任务ID',
  `task_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '任务类型',
  `model` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '模型',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT 'completed' COMMENT '状态',
  `metadata` longtext COLLATE utf8mb4_unicode_ci COMMENT '扩展数据',
  `created_by` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'migration' COMMENT '创建人',
  `updated_by` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'migration' COMMENT '修改人',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `deleted_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '删除人',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除',
  `before_balance` int(11) NOT NULL DEFAULT '0' COMMENT '调整前积分',
  `after_balance` int(11) NOT NULL DEFAULT '0' COMMENT '调整后积分',
  `operator_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作人ID',
  `source` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源',
  PRIMARY KEY (`id`),
  KEY `idx_points_logs_user_created` (`user_id`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='积分流水表';

