BEGIN;
INSERT INTO `scenes` (`id`, `drama_id`, `episode_id`, `location`, `time`, `prompt`, `storyboard_count`, `image_url`, `status`, `local_path`, `created_at`, `updated_at`, `deleted_at`, `created_by`, `updated_by`, `deleted_by`, `is_deleted`) VALUES (1, 1, NULL, '深夜办公室', '现代 · 深夜', 'A modern office at deep night, desk lamp casting a cold, blue light on a cluttered desk with a computer, keyboard, and stacks of documents. The room is dark, with shadows stretching long. The atmosphere is one of oppressive silence and exhaustion. modern, office, night, desk lamp, computer, documents, dark, silence, exhaustion, cinematic lighting', 1, 'static/uploads/e2401e66-c2de-405c-8495-087bd763401b.png', 'processing', NULL, '2026-05-18 04:12:32', '2026-05-18 10:21:05', NULL, 'migration', 'migration', NULL, 0);
INSERT INTO `scenes` (`id`, `drama_id`, `episode_id`, `location`, `time`, `prompt`, `storyboard_count`, `image_url`, `status`, `local_path`, `created_at`, `updated_at`, `deleted_at`, `created_by`, `updated_by`, `deleted_by`, `is_deleted`) VALUES (2, 1, NULL, '金銮殿', '盛唐 · 日', 'The grand throne hall of a Tang Dynasty palace. Ornate carvings and towering pillars line the vast, intimidating space. Sunlight streams through high windows, illuminating dust motes in the air. A majestic dragon throne sits at the far end. The atmosphere is tense and silent. Tang Dynasty, palace, throne hall, grand, ornate, intimidating, sunlight, tense, silent, cinematic, epic', 1, 'static/images/5d683233-1a46-4195-9995-7dbefd0293a9.png', 'completed', NULL, '2026-05-18 04:12:32', '2026-05-18 10:02:40', NULL, 'migration', 'migration', NULL, 0);
INSERT INTO `scenes` (`id`, `drama_id`, `episode_id`, `location`, `time`, `prompt`, `storyboard_count`, `image_url`, `status`, `local_path`, `created_at`, `updated_at`, `deleted_at`, `created_by`, `updated_by`, `deleted_by`, `is_deleted`) VALUES (3, 1, NULL, '长安街市', '盛唐 · 傍晚', 'A bustling street market in the ancient city of Chang\'an at dusk. Lanterns of various shapes and sizes hang from the eaves of traditional wooden buildings, casting a warm, inviting glow. The street is filled with people in Tang Dynasty attire. The atmosphere is lively and vibrant. ancient China, Tang Dynasty, Chang\'an, street market, dusk, lanterns, bustling, lively, vibrant, cinematic', 1, 'static/images/e7b170ee-1ce8-4ee2-8a97-4b1424a784ca.png', 'completed', NULL, '2026-05-18 04:12:32', '2026-05-18 10:11:02', NULL, 'migration', 'migration', NULL, 0);
COMMIT;

-- ----------------------------
-- Table structure for storyboard_characters
-- ----------------------------
DROP TABLE IF EXISTS `storyboard_characters`;
CREATE TABLE `storyboard_characters` (
  `storyboard_id` bigint(20) NOT NULL COMMENT '分镜ID',
  `character_id` bigint(20) NOT NULL COMMENT '角色ID',
  `created_by` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'migration' COMMENT '创建人',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_by` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'migration' COMMENT '修改人',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `deleted_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '删除人',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除',
  PRIMARY KEY (`storyboard_id`,`character_id`),
  KEY `idx_storyboard_characters_storyboard_id` (`storyboard_id`),
  KEY `idx_storyboard_characters_character_id` (`character_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='分镜角色关联表';

