-- ----------------------------
-- Table structure for storyboards
-- ----------------------------
DROP TABLE IF EXISTS `storyboards`;
CREATE TABLE `storyboards` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `episode_id` bigint(20) NOT NULL COMMENT '剧集ID',
  `scene_id` bigint(20) DEFAULT NULL COMMENT '场景ID',
  `storyboard_number` int(11) NOT NULL COMMENT '分镜序号',
  `title` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '标题',
  `location` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '地点',
  `time` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '时间',
  `shot_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '镜头类型',
  `angle` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '镜头角度',
  `movement` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '镜头运动',
  `action` longtext COLLATE utf8mb4_unicode_ci COMMENT '动作',
  `result` longtext COLLATE utf8mb4_unicode_ci COMMENT '结果',
  `atmosphere` longtext COLLATE utf8mb4_unicode_ci COMMENT '氛围',
  `image_prompt` longtext COLLATE utf8mb4_unicode_ci COMMENT '图片提示词',
  `video_prompt` longtext COLLATE utf8mb4_unicode_ci COMMENT '视频提示词',
  `bgm_prompt` longtext COLLATE utf8mb4_unicode_ci COMMENT '背景音乐提示词',
  `sound_effect` longtext COLLATE utf8mb4_unicode_ci COMMENT '音效',
  `dialogue` longtext COLLATE utf8mb4_unicode_ci COMMENT '对白',
  `description` longtext COLLATE utf8mb4_unicode_ci COMMENT '描述',
  `duration` int(11) DEFAULT '0' COMMENT '时长',
  `composed_image` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '合成图片',
  `first_frame_image` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '首帧图片',
  `last_frame_image` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '尾帧图片',
  `reference_images` longtext COLLATE utf8mb4_unicode_ci COMMENT '参考图片',
  `video_url` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '视频地址',
  `tts_audio_url` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'TTS音频地址',
  `subtitle_url` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '字幕地址',
  `composed_video_url` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '合成视频地址',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT 'pending' COMMENT '状态',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  `created_by` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'migration' COMMENT '创建人',
  `updated_by` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'migration' COMMENT '修改人',
  `deleted_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '删除人',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=57 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='分镜表';

-- ----------------------------
-- Records of storyboards
-- ----------------------------
BEGIN;
INSERT INTO `storyboards` (`id`, `episode_id`, `scene_id`, `storyboard_number`, `title`, `location`, `time`, `shot_type`, `angle`, `movement`, `action`, `result`, `atmosphere`, `image_prompt`, `video_prompt`, `bgm_prompt`, `sound_effect`, `dialogue`, `description`, `duration`, `composed_image`, `first_frame_image`, `last_frame_image`, `reference_images`, `video_url`, `tts_audio_url`, `subtitle_url`, `composed_video_url`, `status`, `created_at`, `updated_at`, `deleted_at`, `created_by`, `updated_by`, `deleted_by`, `is_deleted`) VALUES (45, 1, 1, 1, '深夜过劳', '', '', 'MEDIUM_CLOSE_UP', 'EYE_LEVEL', 'PUSH_IN', '沈昭昭低头快速敲击键盘，面色苍白，眼神疲惫。手机屏幕亮起，她抬头看了一眼，突然视线模糊，身体前倾，画面瞬间黑屏。', '', '压抑、疲惫、死寂', 'A modern office at deep night, desk lamp casting a cold, blue light on a cluttered desk with a computer, keyboard, and stacks of documents. A young woman, pale and exhausted, is typing rapidly. The room is dark, with shadows stretching long. modern, office, night, desk lamp, computer, documents, dark, silence, exhaustion, cinematic lighting', '0-4秒：<location>深夜办公室</location>，中近景，<role>沈昭昭</role>低头快速敲击键盘，面色苍白，眼神疲惫。手机屏幕亮起，她抬头看了一眼，突然视线模糊，身体前倾，画面瞬间黑屏。', '低沉压抑的现代电子音，带有心跳般的节奏', '急促的键盘敲击声，连续的手机提示音，最后是沉闷的倒地声和耳鸣声', 'null', '现代办公室，深夜。冷蓝色的台灯光打在凌乱的办公桌上，照亮电脑屏幕、键盘和成堆的文件。周围环境黑暗，阴影拉长。沈昭昭伏案工作，面容憔悴。', 4, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'pending', '2026-05-18 13:56:50', '2026-05-18 13:56:50', NULL, 'migration', 'migration', NULL, 0);
INSERT INTO `storyboards` (`id`, `episode_id`, `scene_id`, `storyboard_number`, `title`, `location`, `time`, `shot_type`, `angle`, `movement`, `action`, `result`, `atmosphere`, `image_prompt`, `video_prompt`, `bgm_prompt`, `sound_effect`, `dialogue`, `description`, `duration`, `composed_image`, `first_frame_image`, `last_frame_image`, `reference_images`, `video_url`, `tts_audio_url`, `subtitle_url`, `composed_video_url`, `status`, `created_at`, `updated_at`, `deleted_at`, `created_by`, `updated_by`, `deleted_by`, `is_deleted`) VALUES (46, 1, 2, 2, '初入大殿', '', '', 'FULL_SHOT', 'LOW_ANGLE', 'PULL_OUT', '沈昭昭猛然睁开眼睛，大口喘气，眼神从迷茫瞬间转为震惊。她发现自己双手被缚，跪在地上。', '', '威严、压迫、震撼', 'The grand throne hall of a Tang Dynasty palace. Sunlight streams through high windows, illuminating dust motes in the air. A young woman in Tang Dynasty male official attire is kneeling in the center, hands bound. Surrounding her are rows of officials. Tang Dynasty, palace, throne hall, grand, ornate, intimidating, sunlight, tense, silent, cinematic, epic', '0-4秒：<location>金銮殿</location>，全景，<role>沈昭昭</role>猛然睁开眼睛，大口喘气，眼神从迷茫瞬间转为震惊。她发现自己双手被缚，跪在地上。镜头缓缓拉远，展现宏大的金銮殿和周围的百官。', '沉重宏大的古代宫廷乐，带有强烈的压迫感', '震天的鼓声，沉重的回音', 'null', '盛唐金銮殿，白天。阳光透过高窗斜射进来，空气中弥漫着灰尘。大殿宽广宏伟，雕梁画栋，巨大的盘龙柱耸立。沈昭昭身穿唐代男装官服，跪在大殿中央。周围是列队整齐的百官。', 4, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'pending', '2026-05-18 13:56:50', '2026-05-18 13:56:50', NULL, 'migration', 'migration', NULL, 0);
INSERT INTO `storyboards` (`id`, `episode_id`, `scene_id`, `storyboard_number`, `title`, `location`, `time`, `shot_type`, `angle`, `movement`, `action`, `result`, `atmosphere`, `image_prompt`, `video_prompt`, `bgm_prompt`, `sound_effect`, `dialogue`, `description`, `duration`, `composed_image`, `first_frame_image`, `last_frame_image`, `reference_images`, `video_url`, `tts_audio_url`, `subtitle_url`, `composed_video_url`, `status`, `created_at`, `updated_at`, `deleted_at`, `created_by`, `updated_by`, `deleted_by`, `is_deleted`) VALUES (47, 1, 2, 3, '当朝发难', '', '', 'MEDIUM_SHOT', 'EYE_LEVEL', 'STATIC', '大臣从班列中跨出一步，手持笏板，指着沈昭昭，表情严厉，厉声呵斥。', '', '紧张、敌意、肃杀', 'An older male official in Tang Dynasty attire, holding a hu (tablet), pointing accusingly with a stern and harsh expression. He stands in front of a row of other officials in a grand palace hall. Tang Dynasty, official, stern, accusing, palace, cinematic lighting', '0-3秒：<location>金銮殿</location>，中景，<role>大臣</role>从班列中跨出一步，手持笏板，指着沈昭昭，表情严厉，厉声呵斥。', '急促紧张的弦乐，烘托危机感', '衣物摩擦声，响亮的回声', '大逆不道！假称诗才惊世，欺君罔上，当斩！', '金銮殿内。年长的大臣身穿圆领宽袖官服，面容冷硬，法令纹深重。他站在班列前缘，姿态拘谨而强硬。背景是其他肃立的官员。', 3, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'pending', '2026-05-18 13:56:50', '2026-05-18 13:56:50', NULL, 'migration', 'migration', NULL, 0);
INSERT INTO `storyboards` (`id`, `episode_id`, `scene_id`, `storyboard_number`, `title`, `location`, `time`, `shot_type`, `angle`, `movement`, `action`, `result`, `atmosphere`, `image_prompt`, `video_prompt`, `bgm_prompt`, `sound_effect`, `dialogue`, `description`, `duration`, `composed_image`, `first_frame_image`, `last_frame_image`, `reference_images`, `video_url`, `tts_audio_url`, `subtitle_url`, `composed_video_url`, `status`, `created_at`, `updated_at`, `deleted_at`, `created_by`, `updated_by`, `deleted_by`, `is_deleted`) VALUES (48, 1, 2, 4, '震惊低语', '', '', 'CLOSE_UP', 'HIGH_ANGLE', 'PUSH_IN', '沈昭昭瞳孔微缩，嘴唇微动，低声自语，眼神中充满不可置信。', '', '惊愕、迷茫、无助', 'A young woman in Tang Dynasty male official attire kneeling on the floor, looking up with an expression of shock and disbelief. Sunlight hits her face. The background is a blurred grand palace ceiling. Tang Dynasty, shock, disbelief, cinematic lighting, high angle', '0-3秒：<location>金銮殿</location>，近景，<role>沈昭昭</role>瞳孔微缩，嘴唇微动，低声自语，眼神中充满不可置信。镜头缓缓推近。', '悬疑感强的低音，带有心跳声', '微弱的呼吸声，心跳声', '这是……唐朝？', '金銮殿内。沈昭昭跪在地上，仰视前方。阳光打在她的脸上，照亮她苍白的面容和紧绷的下颌线。背景是模糊的大殿穹顶。', 3, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'pending', '2026-05-18 13:56:50', '2026-05-18 13:56:50', NULL, 'migration', 'migration', NULL, 0);
INSERT INTO `storyboards` (`id`, `episode_id`, `scene_id`, `storyboard_number`, `title`, `location`, `time`, `shot_type`, `angle`, `movement`, `action`, `result`, `atmosphere`, `image_prompt`, `video_prompt`, `bgm_prompt`, `sound_effect`, `dialogue`, `description`, `duration`, `composed_image`, `first_frame_image`, `last_frame_image`, `reference_images`, `video_url`, `tts_audio_url`, `subtitle_url`, `composed_video_url`, `status`, `created_at`, `updated_at`, `deleted_at`, `created_by`, `updated_by`, `deleted_by`, `is_deleted`) VALUES (49, 1, 2, 5, '帝王之威', '', '', 'MEDIUM_SHOT', 'LOW_ANGLE', 'STATIC', '皇帝端坐在龙椅上，目光深邃锐利，俯视下方。他微微前倾，缓缓开口，声音低沉而充满威压。', '', '威严、压迫、生死攸关', 'A middle-aged emperor in Tang Dynasty dragon robes sitting on a majestic throne, looking down with a deep, piercing gaze. Sunlight highlights his stern facial features. Tang Dynasty, emperor, throne, majestic, stern, cinematic lighting, low angle', '0-4秒：<location>金銮殿</location>，中景，<role>皇帝</role>端坐在龙椅上，目光深邃锐利，俯视下方。他微微前倾，缓缓开口，声音低沉而充满威压。', '沉重缓慢的鼓点，极具压迫感', '沉重的回声，拔刀的金属摩擦声', '既言才华盖世，当殿作诗。若不能——斩。', '金銮殿尽头。皇帝身穿龙纹朝服，头戴高冠，端坐在巨大的龙椅上。高窗斜光勾勒出他冷峻的面部轮廓。背景是金碧辉煌的龙椅和屏风。', 4, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'pending', '2026-05-18 13:56:50', '2026-05-18 13:56:50', NULL, 'migration', 'migration', NULL, 0);
INSERT INTO `storyboards` (`id`, `episode_id`, `scene_id`, `storyboard_number`, `title`, `location`, `time`, `shot_type`, `angle`, `movement`, `action`, `result`, `atmosphere`, `image_prompt`, `video_prompt`, `bgm_prompt`, `sound_effect`, `dialogue`, `description`, `duration`, `composed_image`, `first_frame_image`, `last_frame_image`, `reference_images`, `video_url`, `tts_audio_url`, `subtitle_url`, `composed_video_url`, `status`, `created_at`, `updated_at`, `deleted_at`, `created_by`, `updated_by`, `deleted_by`, `is_deleted`) VALUES (50, 1, 2, 6, '生死一线', '', '', 'EXTREME_CLOSE_UP', 'EYE_LEVEL', 'STATIC', '沈昭昭的瞳孔中倒映出冰冷的刀光。她深吸一口气，闭上眼睛，然后缓缓睁开，眼神变得坚定。', '', '极度紧张、死寂、决绝', 'Extreme close-up of a young woman\'s eyes. A cold reflection of a blade can be seen in her pupils. Her expression transitions from fear to determination. Tang Dynasty, eyes, reflection, blade, determination, cinematic lighting', '0-3秒：<location>金銮殿</location>，特写，<role>沈昭昭</role>的瞳孔中倒映出冰冷的刀光。她深吸一口气，闭上眼睛，然后缓缓睁开，眼神变得坚定。', '音乐骤停，只剩下一声悠长的低音', '清脆的刀鸣声，沉重的呼吸声', 'null', '金銮殿内。沈昭昭的脸部特写。一抹冰冷的刀光闪过她的眼睛。她的面容从惊恐逐渐转为平静和坚毅。', 3, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'pending', '2026-05-18 13:56:50', '2026-05-18 13:56:50', NULL, 'migration', 'migration', NULL, 0);
INSERT INTO `storyboards` (`id`, `episode_id`, `scene_id`, `storyboard_number`, `title`, `location`, `time`, `shot_type`, `angle`, `movement`, `action`, `result`, `atmosphere`, `image_prompt`, `video_prompt`, `bgm_prompt`, `sound_effect`, `dialogue`, `description`, `duration`, `composed_image`, `first_frame_image`, `last_frame_image`, `reference_images`, `video_url`, `tts_audio_url`, `subtitle_url`, `composed_video_url`, `status`, `created_at`, `updated_at`, `deleted_at`, `created_by`, `updated_by`, `deleted_by`, `is_deleted`) VALUES (51, 1, 2, 7, '绝地反击', '', '', 'MEDIUM_SHOT', 'EYE_LEVEL', 'TILT', '沈昭昭缓缓站起身来，虽然双手被缚，但脊背挺直。她转头望向殿外，阳光洒在她的脸上。', '', '破釜沉舟、壮阔、希望', 'A young woman in Tang Dynasty male official attire slowly standing up in a grand palace hall, hands bound but back straight. She looks towards the open doors where bright sunlight pours in, revealing a glimpse of the magnificent city of Chang\'an. Tang Dynasty, standing up, determination, sunlight, cinematic lighting', '0-4秒：<location>金銮殿</location>，中景，<role>沈昭昭</role>缓缓站起身来，虽然双手被缚，但脊背挺直。她转头望向殿外，阳光洒在她的脸上。镜头跟随她起身的动作微微上扬。', '逐渐昂扬的管弦乐，带有史诗感', '衣物摩擦声，微风声', '既来盛唐……便与盛唐争一争。', '金銮殿内。沈昭昭从跪姿缓缓站起。阳光从殿门外倾泻而入，照亮她挺拔的身姿。殿外隐约可见长安城的壮丽景色。', 4, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'pending', '2026-05-18 13:56:50', '2026-05-18 13:56:50', NULL, 'migration', 'migration', NULL, 0);
INSERT INTO `storyboards` (`id`, `episode_id`, `scene_id`, `storyboard_number`, `title`, `location`, `time`, `shot_type`, `angle`, `movement`, `action`, `result`, `atmosphere`, `image_prompt`, `video_prompt`, `bgm_prompt`, `sound_effect`, `dialogue`, `description`, `duration`, `composed_image`, `first_frame_image`, `last_frame_image`, `reference_images`, `video_url`, `tts_audio_url`, `subtitle_url`, `composed_video_url`, `status`, `created_at`, `updated_at`, `deleted_at`, `created_by`, `updated_by`, `deleted_by`, `is_deleted`) VALUES (52, 1, 2, 8, '石破天惊', '', '', 'MEDIUM_CLOSE_UP', 'LOW_ANGLE', 'PUSH_IN', '沈昭昭猛地抬起头，直视前方，高声吟诵。她的声音清亮，充满力量，回荡在整个大殿。', '', '震撼、激昂、气势磅礴', 'A young woman in Tang Dynasty male official attire looking up and reciting loudly with great passion. She is bathed in golden sunlight in a grand palace hall. Tang Dynasty, reciting, passion, sunlight, cinematic lighting, low angle', '0-4秒：<location>金銮殿</location>，中近景，<role>沈昭昭</role>猛地抬起头，直视前方，高声吟诵。她的声音清亮，充满力量，回荡在整个大殿。镜头快速推近。', '高亢激昂的交响乐，达到高潮', '响亮的回声，仿佛惊雷般的声音', '君不见黄河之水天上来——', '金銮殿内。沈昭昭仰头高歌，神情激昂。阳光完全笼罩着她，仿佛给她披上了一层金色的光辉。背景是高大的盘龙柱和穹顶。', 4, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'pending', '2026-05-18 13:56:50', '2026-05-18 13:56:50', NULL, 'migration', 'migration', NULL, 0);
INSERT INTO `storyboards` (`id`, `episode_id`, `scene_id`, `storyboard_number`, `title`, `location`, `time`, `shot_type`, `angle`, `movement`, `action`, `result`, `atmosphere`, `image_prompt`, `video_prompt`, `bgm_prompt`, `sound_effect`, `dialogue`, `description`, `duration`, `composed_image`, `first_frame_image`, `last_frame_image`, `reference_images`, `video_url`, `tts_audio_url`, `subtitle_url`, `composed_video_url`, `status`, `created_at`, `updated_at`, `deleted_at`, `created_by`, `updated_by`, `deleted_by`, `is_deleted`) VALUES (53, 1, 2, 9, '满堂皆惊', '', '', 'FULL_SHOT', 'HIGH_ANGLE', 'PULL_OUT', '群臣面露震惊之色，互相交头接耳。皇帝缓缓从龙椅上站起，眼神中闪过一丝惊讶和赞赏。', '', '震惊、敬畏、不可思议', 'A wide shot of a grand Tang Dynasty palace hall. A young woman stands in the center. Surrounding officials look shocked and are whispering to each other. The emperor slowly stands up from his majestic throne, looking down with surprise and admiration. Tang Dynasty, palace, shocked officials, standing emperor, cinematic lighting, high angle', '0-5秒：<location>金銮殿</location>，全景，<role>群臣</role>面露震惊之色，互相交头接耳。<role>皇帝</role>缓缓从龙椅上站起，眼神中闪过一丝惊讶和赞赏。镜头缓缓拉远，展现整个大殿的震撼场面。', '宏大震撼的合唱声，余音绕梁', '群臣的惊呼声，衣物摩擦声', 'null', '金銮殿全景。沈昭昭站在中央，周围的群臣阵脚大乱，面露惊愕。高高在上的皇帝缓缓站起身来，俯视着沈昭昭。阳光在大殿内形成强烈的光影对比。', 5, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'pending', '2026-05-18 13:56:50', '2026-05-18 13:56:50', NULL, 'migration', 'migration', NULL, 0);
INSERT INTO `storyboards` (`id`, `episode_id`, `scene_id`, `storyboard_number`, `title`, `location`, `time`, `shot_type`, `angle`, `movement`, `action`, `result`, `atmosphere`, `image_prompt`, `video_prompt`, `bgm_prompt`, `sound_effect`, `dialogue`, `description`, `duration`, `composed_image`, `first_frame_image`, `last_frame_image`, `reference_images`, `video_url`, `tts_audio_url`, `subtitle_url`, `composed_video_url`, `status`, `created_at`, `updated_at`, `deleted_at`, `created_by`, `updated_by`, `deleted_by`, `is_deleted`) VALUES (54, 1, 2, 10, '帝王赏识', '', '', 'MEDIUM_SHOT', 'EYE_LEVEL', 'STATIC', '皇帝站在龙椅前，目光深邃地看着沈昭昭，微微点头，嘴角露出一丝不易察觉的微笑。', '', '威严、赞赏、深沉', 'A middle-aged emperor in Tang Dynasty dragon robes standing in front of his throne, looking forward with a deep, appreciative gaze. He nods slightly, a faint smile on his lips. Sunlight outlines his figure. Tang Dynasty, emperor, appreciative, majestic, cinematic lighting', '0-4秒：<location>金銮殿</location>，中景，<role>皇帝</role>站在龙椅前，目光深邃地看着沈昭昭，微微点头，嘴角露出一丝不易察觉的微笑。', '舒缓而宏大的宫廷乐，带有余韵', '沉稳的回声', '此诗，当传万世。', '金銮殿尽头。皇帝站立的半身像。他身穿龙袍，气度非凡。背后的阳光勾勒出他的轮廓，显得高大威猛。他的眼神中充满了对人才的渴望和欣赏。', 4, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'pending', '2026-05-18 13:56:50', '2026-05-18 13:56:50', NULL, 'migration', 'migration', NULL, 0);
INSERT INTO `storyboards` (`id`, `episode_id`, `scene_id`, `storyboard_number`, `title`, `location`, `time`, `shot_type`, `angle`, `movement`, `action`, `result`, `atmosphere`, `image_prompt`, `video_prompt`, `bgm_prompt`, `sound_effect`, `dialogue`, `description`, `duration`, `composed_image`, `first_frame_image`, `last_frame_image`, `reference_images`, `video_url`, `tts_audio_url`, `subtitle_url`, `composed_video_url`, `status`, `created_at`, `updated_at`, `deleted_at`, `created_by`, `updated_by`, `deleted_by`, `is_deleted`) VALUES (55, 1, 2, 11, '长安在我', '', '', 'CLOSE_UP', 'EYE_LEVEL', 'STATIC', '沈昭昭目光坚定地看着前方，嘴角微微上扬，露出一丝自信的微笑。她轻声自语。', '', '自信、坚定、豪情万丈', 'Close-up of a young woman\'s face in Tang Dynasty male official attire. Her eyes are clear and determined, looking forward with a confident smile. Sunlight illuminates her face. Tang Dynasty, confident, determined, cinematic lighting', '0-4秒：<location>金銮殿</location>，近景，<role>沈昭昭</role>目光坚定地看着前方，嘴角微微上扬，露出一丝自信的微笑。她轻声自语。', '轻柔而充满希望的弦乐', '微风声', '既然来了……那便写尽三万里长安。', '金銮殿内。沈昭昭的面部特写。她的眼神清澈而坚定，充满了对未来的憧憬。阳光照在她的脸上，显得无比自信。', 4, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'pending', '2026-05-18 13:56:50', '2026-05-18 13:56:50', NULL, 'migration', 'migration', NULL, 0);
INSERT INTO `storyboards` (`id`, `episode_id`, `scene_id`, `storyboard_number`, `title`, `location`, `time`, `shot_type`, `angle`, `movement`, `action`, `result`, `atmosphere`, `image_prompt`, `video_prompt`, `bgm_prompt`, `sound_effect`, `dialogue`, `description`, `duration`, `composed_image`, `first_frame_image`, `last_frame_image`, `reference_images`, `video_url`, `tts_audio_url`, `subtitle_url`, `composed_video_url`, `status`, `created_at`, `updated_at`, `deleted_at`, `created_by`, `updated_by`, `deleted_by`, `is_deleted`) VALUES (56, 1, 3, 12, '盛唐画卷', '', '', 'EXTREME_LONG_SHOT', 'BIRD_EYE', 'PULL_OUT', '镜头从长安街市缓缓拉远，展现出整个长安城的繁华夜景。灯火辉煌，人声鼎沸。', '', '繁华、壮阔、史诗感', 'A bustling street market in the ancient city of Chang\'an at dusk. Lanterns of various shapes and sizes hang from the eaves of traditional wooden buildings, casting a warm, inviting glow. The street is filled with people in Tang Dynasty attire. The camera pulls back to reveal the magnificent cityscape of Chang\'an with endless lights. ancient China, Tang Dynasty, Chang\'an, street market, dusk, lanterns, bustling, lively, vibrant, cinematic, bird\'s eye view', '0-6秒：<location>长安街市</location>，远景，镜头从长安街市缓缓拉远，展现出整个长安城的繁华夜景。灯火辉煌，人声鼎沸。', '宏大辉煌的盛唐交响乐，气势磅礴', '喧闹的人声，马车声，远处的钟声', 'null', '长安街市，傍晚。街道上挂满了各种形状的灯笼，散发出温暖的光芒。穿着唐代服饰的人们熙熙攘攘，热闹非凡。镜头逐渐拉高，展现出连绵不绝的灯火和宏伟的长安城全貌。', 6, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'pending', '2026-05-18 13:56:50', '2026-05-18 13:56:50', NULL, 'migration', 'migration', NULL, 0);
COMMIT;

-- ----------------------------
-- Table structure for system_settings
-- ----------------------------
DROP TABLE IF EXISTS `system_settings`;
CREATE TABLE `system_settings` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `setting_key` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '设置键',
  `setting_value` longtext COLLATE utf8mb4_unicode_ci COMMENT '设置值',
  `group_name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'system' COMMENT '分组名称',
  `label` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '标签',
  `value_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'string' COMMENT '值类型',
  `is_secret` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否敏感',
  `created_by` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'migration' COMMENT '创建人',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_by` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'migration' COMMENT '修改人',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `deleted_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '删除人',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_system_settings_key` (`setting_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='系统设置表';

-- ----------------------------
-- Records of system_settings
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for video_generations
-- ----------------------------
DROP TABLE IF EXISTS `video_generations`;
CREATE TABLE `video_generations` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `storyboard_id` bigint(20) DEFAULT NULL COMMENT '分镜ID',
  `drama_id` bigint(20) DEFAULT NULL COMMENT '短剧ID',
  `provider` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '供应商标识',
  `prompt` longtext COLLATE utf8mb4_unicode_ci COMMENT '提示词',
  `model` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '模型',
  `image_gen_id` bigint(20) DEFAULT NULL COMMENT '图片生成ID',
  `reference_mode` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '参考模式',
  `image_url` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '图片地址',
  `first_frame_url` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '首帧地址',
  `last_frame_url` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '尾帧地址',
  `reference_image_urls` longtext COLLATE utf8mb4_unicode_ci COMMENT '参考图片地址',
  `duration` int(11) DEFAULT NULL COMMENT '时长',
  `fps` int(11) DEFAULT NULL COMMENT '帧率',
  `resolution` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '分辨率',
  `aspect_ratio` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '宽高比',
  `style` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '风格',
  `motion_level` int(11) DEFAULT NULL COMMENT '运动强度',
  `camera_motion` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '镜头运动',
  `seed` bigint(20) DEFAULT NULL COMMENT '随机种子',
  `video_url` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '视频地址',
  `minio_url` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '对象存储地址',
  `local_path` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '本地路径',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT 'pending' COMMENT '状态',
  `task_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '任务ID',
  `error_msg` longtext COLLATE utf8mb4_unicode_ci COMMENT '错误信息',
  `width` int(11) DEFAULT NULL COMMENT '宽度',
  `height` int(11) DEFAULT NULL COMMENT '高度',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `completed_at` datetime DEFAULT NULL COMMENT '完成时间',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  `created_by` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'migration' COMMENT '创建人',
  `updated_by` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'migration' COMMENT '修改人',
  `deleted_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '删除人',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除',
  `reference_video_urls` json DEFAULT NULL COMMENT '参考视频URL列表',
  `reference_audio_urls` json DEFAULT NULL COMMENT '参考音频URL列表',
  `frames` int(11) DEFAULT NULL COMMENT '输出帧数',
  `generate_audio` tinyint(1) DEFAULT NULL COMMENT '是否生成音频',
  `camera_fixed` tinyint(1) DEFAULT NULL COMMENT '是否固定镜头',
  `watermark` tinyint(1) DEFAULT NULL COMMENT '是否添加水印',
  `return_last_frame` tinyint(1) DEFAULT NULL COMMENT '是否返回尾帧',
  `service_tier` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '推理服务层级',
  `execution_expires_after` int(11) DEFAULT NULL COMMENT '任务执行过期秒数',
  `callback_url` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '任务回调地址',
  `draft` tinyint(1) DEFAULT NULL COMMENT '是否草稿模式',
  `draft_task_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '草稿任务ID',
  `tools` json DEFAULT NULL COMMENT '视频生成工具配置',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='视频生成记录表';

-- ----------------------------
-- Records of video_generations
-- ----------------------------
BEGIN;
