-- ----------------------------
-- Table structure for video_merges
-- ----------------------------
DROP TABLE IF EXISTS `video_merges`;
CREATE TABLE `video_merges` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `episode_id` bigint(20) DEFAULT NULL COMMENT '剧集ID',
  `drama_id` bigint(20) DEFAULT NULL COMMENT '短剧ID',
  `title` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '标题',
  `provider` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '供应商标识',
  `model` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模型',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT 'pending' COMMENT '状态',
  `scenes` longtext COLLATE utf8mb4_unicode_ci COMMENT '场景数据',
  `merged_url` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '合成地址',
  `duration` int(11) DEFAULT NULL COMMENT '时长',
  `task_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '任务ID',
  `error_msg` longtext COLLATE utf8mb4_unicode_ci COMMENT '错误信息',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `completed_at` datetime DEFAULT NULL COMMENT '完成时间',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  `created_by` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'migration' COMMENT '创建人',
  `updated_by` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'migration' COMMENT '修改人',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `deleted_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '删除人',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='视频合成记录表';

